  // FAQ
  "faq.eyebrow": { pt: "FAQ", en: "FAQ", es: "FAQ" },
  "faq.title1": { pt: "Perguntas,", en: "Questions,", es: "Preguntas," },
  "faq.title2": { pt: "respondidas", en: "answered", es: "respondidas" },
  "faq.q1": { pt: "O PvP Pro é um jogo Play-to-Earn?", en: "Is PvP Pro a Play-to-Earn game?", es: "¿PvP Pro es un juego Play-to-Earn?" },
  "faq.a1": {
    pt: "Não. O PvP Pro é PvP baseado em habilidade. Os ganhos vêm de vencer partidas contra outros jogadores — nunca de emissão ou recompensas inflacionárias.",
    en: "No. PvP Pro is skill-based PvP. Earnings come from winning matches against other players — never from emissions or inflationary rewards.",
    es: "No. PvP Pro es PvP basado en habilidad. Las ganancias vienen de ganar partidas contra otros jugadores — nunca de emisiones o recompensas inflacionarias.",
  },
  "faq.q2": { pt: "O que dá lastro ao token PVP?", en: "What backs the PVP token?", es: "¿Qué respalda al token PVP?" },
  "faq.a2": {
    pt: "Receita real do protocolo, vinda de partidas competitivas, financia um treasury transparente que executa buybacks sistemáticos.",
    en: "Real protocol revenue from competitive matches funds a transparent treasury that executes systematic buybacks.",
    es: "El ingreso real del protocolo, proveniente de partidas competitivas, financia un treasury transparente que ejecuta buybacks sistemáticos.",
  },
  "faq.q3": { pt: "Quem pode se tornar um Founder?", en: "Who can become a Founder?", es: "¿Quién puede convertirse en Founder?" },
  "faq.a3": {
    pt: "Qualquer pessoa que participar da Venda Genesis pode se tornar um Genesis Founder. Ao entrar, você recebe PVP, Founder NFT e os benefícios correspondentes ao seu Tier, incluindo participação nas taxas geradas pelas partidas, torneios gratuitos, governança e acesso antecipado, conforme o nível escolhido e as regras do programa.",
    en: "Anyone who takes part in the Genesis Sale can become a Genesis Founder. By joining, you receive PVP, a Founder NFT and the benefits tied to your Tier, including a share of the fees generated by matches, free tournaments, governance and early access, according to the chosen level and the program's rules.",
    es: "Cualquier persona que participe en la Venta Genesis puede convertirse en Genesis Founder. Al entrar, recibes PVP, un Founder NFT y los beneficios correspondientes a tu Tier, incluyendo participación en las tarifas generadas por las partidas, torneos gratuitos, gobernanza y acceso anticipado, según el nivel elegido y las reglas del programa.",
  },
  "faq.q4": { pt: "Como funciona a participação dos Founders nas taxas?", en: "How does Founders' share of the fees work?", es: "¿Cómo funciona la participación de los Founders en las tarifas?" },
  "faq.a4": {
    pt: "Os 2% das taxas das partidas destinados aos Genesis Founders são distribuídos automaticamente e de forma proporcional à quantidade de PVP de cada Founder. Quanto maior a quantidade de PVP, maior a participação no pool de Founders. O recebimento é automático, sem necessidade de solicitação manual.",
    en: "The 2% of match fees allocated to Genesis Founders is distributed automatically and proportionally to each Founder's PVP holdings. The more PVP you hold, the bigger your share of the Founders pool. Payout is automatic — no manual claim request needed.",
    es: "El 2% de las tarifas de las partidas destinado a los Genesis Founders se distribuye automáticamente y de forma proporcional a la cantidad de PVP de cada Founder. Cuanto mayor sea la cantidad de PVP, mayor será la participación en el pool de Founders. El pago es automático, sin necesidad de solicitud manual.",
  },
  "faq.q5": { pt: "Em qual rede o PvP Pro é construído?", en: "Which network is PvP Pro built on?", es: "¿En qué red está construido PvP Pro?" },
  "faq.a5": {
    pt: "O PvP Pro é lançado na Base Mainnet, por causa das taxas baixas, finalidade rápida e amplo suporte de carteiras.",
    en: "PvP Pro launches on Base Mainnet for low fees, fast finality, and broad wallet support.",
    es: "PvP Pro se lanza en Base Mainnet, por sus tarifas bajas, finalidad rápida y amplio soporte de carteras.",
  },
  "faq.q6": { pt: "Quando o token vai poder ser resgatado?", en: "When will the token be claimable?", es: "¿Cuándo se podrá reclamar el token?" },
  "faq.a6": {
    pt: "O resgate abre no TGE, depois que a Venda Genesis for concluída e os contratos forem auditados de forma independente.",
    en: "Claim opens at TGE, after the Genesis Sale completes and contracts are independently audited.",
    es: "El reclamo se abre en el TGE, después de que la Venta Genesis concluya y los contratos sean auditados de forma independiente.",
  },
  "faq.q7": { pt: "Como eu conecto minha carteira?", en: "How do I connect my wallet?", es: "¿Cómo conecto mi cartera?" },
  "faq.a7": {
    pt: "Use o botão Connect Wallet. MetaMask, Coinbase Wallet e WalletConnect são suportados.",
    en: "Use the Connect Wallet button. MetaMask, Coinbase Wallet, and WalletConnect are supported.",
    es: "Usa el botón Connect Wallet. MetaMask, Coinbase Wallet y WalletConnect son compatibles.",
  },

